import{_ as e,o as a,c as r,ag as i}from"./chunks/framework.qXLDknWC.js";const u=JSON.parse('{"title":"Vault Organization","description":"","frontmatter":{},"headers":[],"relativePath":"features/vault-organization.md","filePath":"features/vault-organization.md"}'),o={name:"features/vault-organization.md"};function n(l,t,s,h,c,d){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="vault-organization" tabindex="-1">Vault Organization <a class="header-anchor" href="#vault-organization" aria-label="Permalink to &quot;Vault Organization&quot;">​</a></h1><p>The character library is your home base — a grid view of all your characters with tools for finding, duplicating, and managing your collection.</p><h2 id="library-grid-view" tabindex="-1">Library Grid View <a class="header-anchor" href="#library-grid-view" aria-label="Permalink to &quot;Library Grid View&quot;">​</a></h2><p>All characters are displayed as portrait-style cards in a responsive grid that adapts to your screen width:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Screen</th><th style="text-align:left;">Columns</th></tr></thead><tbody><tr><td style="text-align:left;">Mobile</td><td style="text-align:left;">2</td></tr><tr><td style="text-align:left;">Small tablet</td><td style="text-align:left;">3</td></tr><tr><td style="text-align:left;">Tablet</td><td style="text-align:left;">4</td></tr><tr><td style="text-align:left;">Desktop</td><td style="text-align:left;">5</td></tr><tr><td style="text-align:left;">Wide desktop</td><td style="text-align:left;">6</td></tr></tbody></table><p>Each card shows the character&#39;s portrait thumbnail, name, and last-opened time. Characters are always sorted alphabetically by name (case-insensitive, with natural number ordering — &quot;Character 2&quot; comes before &quot;Character 10&quot;).</p><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><p>Use the search bar (in the header on desktop, below the header on mobile) to filter characters by name. The grid updates in real-time as you type.</p><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><p>When you have at least one character, a <strong>Continue</strong> pill appears in the top-right of the library. It jumps straight to the character you most recently opened (or most recently updated), so you can pick up right where you left off.</p><h2 id="quick-actions" tabindex="-1">Quick Actions <a class="header-anchor" href="#quick-actions" aria-label="Permalink to &quot;Quick Actions&quot;">​</a></h2><p>Hover over a character card (or tap on mobile) to access quick actions:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Duplicate</strong></td><td style="text-align:left;">Creates a copy of the character with &quot; (Copy)&quot; appended to the name</td></tr><tr><td style="text-align:left;"><strong>Delete</strong></td><td style="text-align:left;">Removes the character from your vault after a confirmation dialog</td></tr></tbody></table><p>Click anywhere on the card to open it in the workspace.</p><h2 id="creating-a-new-character" tabindex="-1">Creating a New Character <a class="header-anchor" href="#creating-a-new-character" aria-label="Permalink to &quot;Creating a New Character&quot;">​</a></h2><p>Click <strong>Create New</strong> in the header to reveal an inline form. Type a name and press <strong>Create</strong> — the new character appears in the grid immediately.</p><h2 id="importing" tabindex="-1">Importing <a class="header-anchor" href="#importing" aria-label="Permalink to &quot;Importing&quot;">​</a></h2><p>Click <strong>Import</strong> in the header to open a file picker. You can import <code>.png</code> character card images or <code>.json</code> character files. See <a href="/CharacterVault/docs/features/import-export">Import &amp; Export</a> for full details.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><p>The library paginates automatically — 12 cards per page on mobile, 18 on desktop. Use the <strong>Previous</strong> and <strong>Next</strong> buttons at the bottom to navigate.</p><h2 id="loading" tabindex="-1">Loading <a class="header-anchor" href="#loading" aria-label="Permalink to &quot;Loading&quot;">​</a></h2><p>When the library first loads, skeleton placeholders appear while character thumbnails are preloaded in the background. This prevents the grid from shifting as images load in.</p><h2 id="offline-first-storage" tabindex="-1">Offline-First Storage <a class="header-anchor" href="#offline-first-storage" aria-label="Permalink to &quot;Offline-First Storage&quot;">​</a></h2><p>All character data is stored locally in your browser. No server is required to use Character Vault.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>AI features (Orion assistant, AI toolbar) require an internet connection to reach your configured API endpoint.</p></div><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/getting-started/creating-characters">Create a new character</a></li><li><a href="/CharacterVault/docs/features/import-export">Import existing characters</a></li></ul>',27)])])}const g=e(o,[["render",n]]);export{u as __pageData,g as default};
